"""The ledger: validated transactions and exact balances."""
import re

from tallybook.accounts import Chart, parent_path
from tallybook.currency import RateTable, is_date
from tallybook.dates import format_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.money import Money, format_minor
from tallybook.model import Posting, Transaction

_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


class LedgerError(ValidationError):
    pass


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _one_line(value):
    return isinstance(value, str) and "\n" not in value and "\r" not in value


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation -----------------------------------------------------
    def _prepare(self, tx, ids_in_use):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("transaction date must be a date, not %r" % (tx.date,))
        if tx.flag not in ("*", "!") or not isinstance(tx.flag, str):
            raise LedgerError("invalid flag %r: use * or !" % (tx.flag,))
        if not _one_line(tx.payee):
            raise LedgerError("payee must be text without a line break")
        if not _one_line(tx.narration):
            raise LedgerError("narration must be text without a line break")
        if not isinstance(tx.tags, (list, tuple, set, frozenset)):
            raise LedgerError("tags must be a list of names")
        for tag in tx.tags:
            if not isinstance(tag, str) or not _TAG.fullmatch(tag):
                raise LedgerError("invalid tag %r" % (tag,))
        if not isinstance(tx.postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        postings = list(tx.postings)
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: %r" % (p,))
            if not _one_line(p.note):
                raise LedgerError("a posting note must be text without a line break")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("a posting amount must be money or None")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % (p.account,))
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, format_date(tx.date)))
            self._check_currency(p.account, p.amount)
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = sorted(c for c, v in sums.items() if v != 0)
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            gap = postings[i]
            filled = []
            for cur in off:
                amount = Money(-sums[cur], cur)
                self._check_currency(gap.account, amount)
                filled.append(Posting(gap.account, amount, gap.note))
            postings[i:i + 1] = filled
        elif off:
            raise LedgerError("transaction does not balance: " + ", ".join(
                "%s %s" % (c, format_minor(sums[c], c)) for c in off))
        if tx.id is None:
            new_id = self._max_id + 1
        else:
            if not _is_int(tx.id) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in ids_in_use:
                raise LedgerError("transaction id %d already exists" % tx.id)
            new_id = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings,
                           tuple(sorted(set(tx.tags))), tx.flag, new_id)

    def _check_currency(self, account, amount):
        if amount is None:
            return
        held = self.chart.get(account).currency
        if held is not None and held != amount.currency:
            raise LedgerError("account %s only holds %s, not %s" % (account, held, amount.currency))

    def _store(self, stored):
        self._txs[stored.id] = stored
        if stored.id > self._max_id:
            self._max_id = stored.id

    # -- changing ---------------------------------------------------------
    def add(self, tx):
        stored = self._prepare(tx, self._txs)
        self._store(stored)
        return stored

    def add_many(self, transactions):
        snapshot = (dict(self._txs), self._max_id)
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = snapshot
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if tx.id is not None and tx.id != id:
            raise LedgerError("transaction id %s does not match %s" % (tx.id, id))
        probe = Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None)
        stored = self._prepare(probe, self._txs)
        stored.id = id
        self._txs[id] = stored
        return stored

    def remove(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs.pop(id)

    # -- reading ------------------------------------------------------------
    def get(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs[id]

    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    def _sums(self, as_of, rollup):
        if as_of is not None and not is_date(as_of):
            raise LedgerError("as_of must be a date, not %r" % (as_of,))
        out = {}
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            if p.amount is None:
                continue
            path = p.account
            while path is not None:
                cur = out.setdefault(path, {})
                cur[p.amount.currency] = cur.get(p.amount.currency, 0) + p.amount.minor
                path = parent_path(path) if rollup else None
        return out

    def _clean(self, sums):
        out = {}
        for account, cur in sums.items():
            kept = {c: v for c, v in cur.items() if v != 0}
            if kept:
                out[account] = kept
        return out

    def balances(self, as_of=None):
        return self._clean(self._sums(as_of, False))

    def rollup_balances(self, as_of=None):
        return self._clean(self._sums(as_of, True))

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account: %s" % (account,))
        table = self.rollup_balances(as_of) if rollup else self.balances(as_of)
        mine = table.get(account, {})
        if currency is not None:
            return Money(mine.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in mine.items()}
"""Money: whole minor units plus a currency code, never floats."""
import re

from tallybook.currency import CURRENCIES, CurrencyError, currency
from tallybook.errors import ValidationError


class MoneyError(ValidationError):
    pass


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def round_div(n, d):
    """n / d rounded to the nearest integer, halves away from zero (d > 0)."""
    if not _is_int(n) or not _is_int(d):
        raise MoneyError("round_div needs two integers")
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, not %d" % d)
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def format_minor(minor, cur):
    exponent = currency(cur).exponent
    if not _is_int(minor):
        raise MoneyError("minor units must be an integer, not %r" % (minor,))
    digits = str(abs(minor))
    if exponent:
        digits = digits.rjust(exponent + 1, "0")
        digits = digits[:-exponent] + "." + digits[-exponent:]
    return "-" + digits if minor < 0 else digits


_AMOUNT = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def parse_amount(text, cur):
    exponent = currency(cur).exponent
    if not isinstance(text, str):
        raise MoneyError("invalid amount '%s': not text" % (text,))
    m = _AMOUNT.fullmatch(text)
    if m is None:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.group(1), m.group(2), m.group(3)
    if frac is not None and len(frac) > exponent:
        raise MoneyError("invalid amount '%s': %s has %d decimals" % (text, cur, exponent))
    minor = int(whole + (frac or "").ljust(exponent, "0"))
    return -minor if sign == "-" else minor


class Money:
    __slots__ = ("_minor", "_currency")

    def __init__(self, minor, currency_code):
        if not _is_int(minor):
            raise MoneyError("minor units must be an integer, not %r" % (minor,))
        currency(currency_code)
        object.__setattr__(self, "_minor", minor)
        object.__setattr__(self, "_currency", currency_code)

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    minor = property(lambda self: self._minor)
    currency = property(lambda self: self._currency)
    exponent = property(lambda self: CURRENCIES[self._currency].exponent)

    @classmethod
    def zero(cls, cur):
        return cls(0, cur)

    @classmethod
    def of(cls, text, cur):
        return cls(parse_amount(text, cur), cur)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("invalid money '%s': not text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise MoneyError("invalid money '%s': write an amount, one space and a currency" % text)
        return cls.of(parts[0], parts[1])

    def amount_str(self):
        return format_minor(self._minor, self._currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self._currency)

    def __repr__(self):
        return "Money(%d, '%s')" % (self._minor, self._currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self._minor == other._minor and self._currency == other._currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self._minor, self._currency))

    def _same(self, other, verb):
        if self._currency != other._currency:
            raise MoneyError("cannot %s %s and %s: different currencies"
                             % (verb, self._currency, other._currency))

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "add")
        return Money(self._minor + other._minor, self._currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "subtract")
        return Money(self._minor - other._minor, self._currency)

    def __neg__(self):
        return Money(-self._minor, self._currency)

    def __abs__(self):
        return Money(abs(self._minor), self._currency)

    def __mul__(self, other):
        if not _is_int(other):
            return NotImplemented
        return Money(self._minor * other, self._currency)

    __rmul__ = __mul__

    def _cmp(self, other, op):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "compare")
        return op(self._minor, other._minor)

    def __lt__(self, other):
        return self._cmp(other, lambda a, b: a < b)

    def __le__(self, other):
        return self._cmp(other, lambda a, b: a <= b)

    def __gt__(self, other):
        return self._cmp(other, lambda a, b: a > b)

    def __ge__(self, other):
        return self._cmp(other, lambda a, b: a >= b)

    def is_zero(self):
        return self._minor == 0

    def sign(self):
        return (self._minor > 0) - (self._minor < 0)

    def scale(self, num, den=1):
        if not _is_int(num) or not _is_int(den):
            raise MoneyError("scale needs integers")
        if den == 0:
            raise MoneyError("scale: the denominator may not be zero")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self._minor * num, den), self._currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)):
            raise MoneyError("weights must be a list of integers")
        weights = list(weights)
        if not weights or not all(_is_int(w) and w >= 0 for w in weights):
            raise MoneyError("weights must be non-negative integers, at least one of them")
        total = sum(weights)
        if total <= 0:
            raise MoneyError("weights must add up to more than zero")
        amount = abs(self._minor)
        shares = [amount * w // total for w in weights]
        rems = [amount * w % total for w in weights]
        left = amount - sum(shares)
        order = sorted(range(len(weights)), key=lambda i: (-rems[i], i))
        for i in order[:left]:
            shares[i] += 1
        if self._minor < 0:
            shares = [-s for s in shares]
        return [Money(s, self._currency) for s in shares]
"""Strict dates, month arithmetic and periods."""
import re
from datetime import date, datetime, timedelta

from tallybook.errors import ParseError


class DateError(ParseError):
    pass


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date '%s': not text" % (text,))
    m = _DATE.fullmatch(text)
    if m is None:
        raise DateError("invalid date '%s': write YYYY-MM-DD" % text)
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text)


def format_date(d):
    if not _is_date(d):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers")
    if not 1 <= year <= 9999 or not 1 <= month <= 12:
        raise DateError("no such month: %s-%s" % (year, month))
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - timedelta(days=1)).day


def add_months(d, n):
    if not _is_date(d):
        raise DateError("not a date: %r" % (d,))
    if not _is_int(n):
        raise DateError("months must be a whole number, not %r" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    year, month = divmod(total, 12)
    month += 1
    if not 1 <= year <= 9999:
        raise DateError("date out of range: %s moved by %d months" % (format_date(d), n))
    return date(year, month, min(d.day, last_day(year, month)))


_YEAR = re.compile(r"([0-9]{4})")
_MONTH = re.compile(r"([0-9]{4})-([0-9]{2})")
_QUARTER = re.compile(r"([0-9]{4})-Q([1-4])")
_RANGE = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})")


class Period:
    __slots__ = ("_start", "_end")

    def __init__(self, start, end):
        if not _is_date(start) or not _is_date(end):
            raise DateError("a period needs two dates, not %r and %r" % (start, end))
        if end < start:
            raise DateError("empty period: %s ends before %s" % (format_date(end), format_date(start)))
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)

    def __setattr__(self, name, value):
        raise AttributeError("Period is immutable")

    start = property(lambda self: self._start)
    end = property(lambda self: self._end)

    def __eq__(self, other):
        return isinstance(other, Period) and self._start == other._start and self._end == other._end

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self._start, self._end))

    def __repr__(self):
        return "Period(%r, %r)" % (self._start, self._end)

    def __str__(self):
        return self.label

    def contains(self, d):
        if not _is_date(d):
            raise DateError("not a date: %r" % (d,))
        return self._start <= d <= self._end

    @property
    def days(self):
        return (self._end - self._start).days + 1

    @property
    def label(self):
        s, e = self._start, self._end
        if s.day == 1 and e.year == s.year:
            if s.month == 1 and e.month == 12 and e.day == 31:
                return "%04d" % s.year
            if s.month in (1, 4, 7, 10) and e.month == s.month + 2 and e.day == last_day(e.year, e.month):
                return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
            if e.month == s.month and e.day == last_day(s.year, s.month):
                return "%04d-%02d" % (s.year, s.month)
        return "%s..%s" % (format_date(s), format_date(e))

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period '%s': not text" % (text,))
        try:
            m = _YEAR.fullmatch(text)
            if m:
                y = int(text)
                return cls(date(y, 1, 1), date(y, 12, 31))
            m = _MONTH.fullmatch(text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                return cls(date(y, mo, 1), date(y, mo, last_day(y, mo)))
            m = _QUARTER.fullmatch(text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                first = (q - 1) * 3 + 1
                return cls(date(y, first, 1), date(y, first + 2, last_day(y, first + 2)))
            m = _RANGE.fullmatch(text)
            if m:
                return cls(parse_date(m.group(1)), parse_date(m.group(2)))
        except (DateError, ValueError) as err:
            raise DateError("invalid period '%s': %s" % (text, err))
        raise DateError("invalid period '%s': write 2024, 2024-03, 2024-Q1 or 2024-03-01..2024-03-31" % text)

    def next(self):
        s, e = self._start, self._end
        try:
            label = self.label
            if len(label) == 4:
                return Period(date(s.year + 1, 1, 1), date(s.year + 1, 12, 31))
            if len(label) == 7 and label[5] == "Q":
                first = s.month + 3
                year = s.year
                if first > 12:
                    first, year = 1, year + 1
                return Period(date(year, first, 1), date(year, first + 2, last_day(year, first + 2)))
            if len(label) == 7:
                nxt = add_months(s, 1)
                return Period(nxt, date(nxt.year, nxt.month, last_day(nxt.year, nxt.month)))
            start = e + timedelta(days=1)
            return Period(start, start + timedelta(days=self.days - 1))
        except (ValueError, OverflowError):
            raise DateError("no period after %s" % self.label)


_STEPS = ("week", "month", "quarter", "year")


def _containing(d, step):
    if step == "week":
        monday = d - timedelta(days=d.weekday())
        return Period(monday, monday + timedelta(days=6))
    if step == "month":
        return Period(date(d.year, d.month, 1), date(d.year, d.month, last_day(d.year, d.month)))
    if step == "quarter":
        first = (d.month - 1) // 3 * 3 + 1
        return Period(date(d.year, first, 1), date(d.year, first + 2, last_day(d.year, first + 2)))
    return Period(date(d.year, 1, 1), date(d.year, 12, 31))


def periods(start, end, step):
    if not _is_date(start) or not _is_date(end):
        raise DateError("periods needs two dates")
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step '%s': use week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("%s is before %s" % (format_date(end), format_date(start)))
    try:
        p = _containing(start, step)
        out = [p]
        while p.end < end:
            p = p.next()
            out.append(p)
    except (ValueError, OverflowError):
        raise DateError("periods run past the end of the calendar")
    return out
"""The chart of accounts."""
import re

from tallybook.currency import CURRENCIES, is_date
from tallybook.dates import format_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account

ROOTS = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOTS.values())

_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")


class ChartError(ValidationError):
    def __init__(self, message="", code=None, detail=None):
        ValidationError.__init__(self, message, detail)
        if code is not None:
            self.code = code


def valid_path(text):
    if not isinstance(text, str):
        return False
    parts = text.split(":")
    if parts[0] not in ROOTS:
        return False
    return all(_SEGMENT.fullmatch(p) for p in parts[1:])


def _need_valid(path):
    if not valid_path(path):
        raise ChartError("invalid account path '%s'" % (path,))


def parent_path(path):
    _need_valid(path)
    head, sep, _ = path.rpartition(":")
    return head if sep else None


def account_type(path):
    _need_valid(path)
    return ROOTS[path.split(":")[0]]


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern '%s'" % (pattern,))
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and not _SEGMENT.fullmatch(p):
            raise ChartError("invalid account pattern '%s'" % pattern)
    return parts


def _match_parts(pat, seg):
    # pat: pattern segments; seg: path segments; ** = one or more segments
    if not pat:
        return not seg
    head = pat[0]
    if head == "**":
