"""Export transactions as CSV or JSON, and draw plain text tables."""
import json

from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, MoneyError
from tallybook.currency import CurrencyError

CSV_HEADER = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


class ExportError(ValidationError):
    pass


# -- CSV ---------------------------------------------------------------------

def _csv_field(value):
    text = "" if value is None else str(value)
    if any(ch in text for ch in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def _csv_record(cells):
    return ",".join(_csv_field(c) for c in cells) + "\n"


def to_csv(headers, rows):
    out = [_csv_record(list(headers))]
    for row in rows:
        out.append(_csv_record(list(row)))
    return "".join(out)


def transactions_to_csv(txs):
    out = [_csv_record(CSV_HEADER)]
    for tx in txs:
        tags = ";".join(sorted(set(tx.tags)))
        head = ["" if tx.id is None else str(tx.id), format_date(tx.date), tx.flag, tx.payee, tx.narration, tags]
        if not tx.postings:
            out.append(_csv_record(head + ["", "", "", ""]))
            continue
        for p in tx.postings:
            if p.amount is None:
                amount, cur = "", ""
            else:
                amount, cur = p.amount.amount_str(), p.amount.currency
            out.append(_csv_record(head + [p.account, amount, cur, p.note]))
    return "".join(out)


# -- JSON --------------------------------------------------------------------

def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": sorted(set(tx.tags)),
        "postings": [
            {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
            for p in tx.postings
        ],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def _is_whole(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _read_posting(item, where):
    if not isinstance(item, dict):
        raise ExportError("%s: a posting must be an object" % where)
    for key in item:
        if key not in _POSTING_KEYS:
            raise ExportError("%s: unknown key %r" % (where, key))
    account = item.get("account")
    if not isinstance(account, str):
        raise ExportError("%s: account is missing or is not text" % where)
    note = item.get("note", "")
    if not isinstance(note, str):
        raise ExportError("%s: note must be text" % where)
    raw = item.get("amount")
    amount = None
    if raw is not None:
        if not isinstance(raw, dict) or set(raw) != {"amount", "currency"}:
            raise ExportError("%s: amount must be null or an object with amount and currency" % where)
        if not isinstance(raw["amount"], str) or not isinstance(raw["currency"], str):
            raise ExportError("%s: amount and currency must be text" % where)
        try:
            amount = Money.of(raw["amount"], raw["currency"])
        except (MoneyError, CurrencyError) as err:
            raise ExportError("%s: %s" % (where, err.message))
    return Posting(account, amount, note)


def _read_transaction(item, number):
    where = "transaction %d" % number
    if not isinstance(item, dict):
        raise ExportError("%s: must be an object" % where)
    for key in item:
        if key not in _TX_KEYS:
            raise ExportError("%s: unknown key %r" % (where, key))
    for key in ("date", "payee", "postings"):
        if key not in item:
            raise ExportError("%s: missing %s" % (where, key))
    if not isinstance(item["date"], str):
        raise ExportError("%s: date must be text YYYY-MM-DD" % where)
    try:
        day = parse_date(item["date"])
    except DateError as err:
        raise ExportError("%s: %s" % (where, err.message))
    tx_id = item.get("id")
    if tx_id is not None and (not _is_whole(tx_id) or tx_id < 1):
        raise ExportError("%s: id must be null or a whole number of at least 1" % where)
    flag = item.get("flag", "*")
    if not isinstance(flag, str) or flag not in ("*", "!"):
        raise ExportError("%s: flag must be * or !" % where)
    payee = item["payee"]
    if not isinstance(payee, str):
        raise ExportError("%s: payee must be text" % where)
    narration = item.get("narration", "")
    if not isinstance(narration, str):
        raise ExportError("%s: narration must be text" % where)
    tags = item.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ExportError("%s: tags must be a list of text" % where)
    raw_postings = item["postings"]
    if not isinstance(raw_postings, list):
        raise ExportError("%s: postings must be a list" % where)
    postings = [_read_posting(p, "%s posting %d" % (where, i)) for i, p in enumerate(raw_postings, 1)]
    return Transaction(day, payee, narration, postings, tuple(sorted(set(tags))), flag, tx_id)


def transactions_from_json(text):
    if not isinstance(text, str):
        raise ExportError("the JSON must be text")
    try:
        data = json.loads(text)
    except (ValueError, RecursionError) as err:
        raise ExportError("not valid JSON: %s" % (err,))
    if not isinstance(data, list):
        raise ExportError("the JSON must be an array of transactions")
    return [_read_transaction(item, i) for i, item in enumerate(data, 1)]


# -- tables ------------------------------------------------------------------

def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    titles = [_cell(h) for h in headers]
    if not titles:
        return ""
    n = len(titles)
    if align is None:
        letters = ["l"] * n
    elif isinstance(align, (str, list, tuple)):
        letters = list(align)
    else:
        raise ExportError("align must be text or a list of l and r")
    if len(letters) != n:
        raise ExportError("align has %d letters for %d columns" % (len(letters), n))
    for letter in letters:
        if letter not in ("l", "r") or not isinstance(letter, str):
            raise ExportError("align letters must be l or r, not %r" % (letter,))
    body = []
    for row in rows:
        cells = [_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("a row has %d cells for %d columns" % (len(cells), n))
        body.append(cells)
    widths = [len(t) for t in titles]
    for cells in body:
        for i, c in enumerate(cells):
            if len(c) > widths[i]:
                widths[i] = len(c)

    def line(cells):
        parts = []
        for i, c in enumerate(cells):
            parts.append(c.ljust(widths[i]) if letters[i] == "l" else c.rjust(widths[i]))
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(titles), line(["-" * w for w in widths])]
    for cells in body:
        out.append(line(cells))
    return "".join(out)

