"""Budgets: how much I may spend, and how I am doing."""
import re
from dataclasses import dataclass
from datetime import date
from decimal import Decimal
from fractions import Fraction
from typing import Tuple

from tallybook.currency import is_date
from tallybook.dates import Period
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict
from tallybook.money import Money, round_div

_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")
_KINDS = ("month", "quarter", "year")
_STEP = {"month": 1, "quarter": 3, "year": 12}


class BudgetError(ValidationError):
    pass


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise BudgetError("invalid budget pattern %r: write an account path such as Expenses:Food" % (pattern,))
    for seg in pattern.split(":"):
        if seg != "*" and not _SEGMENT.fullmatch(seg):
            raise BudgetError("invalid budget pattern '%s': bad segment '%s'" % (pattern, seg))


@dataclass(frozen=True)
class Budget:
    pattern: str
    period_kind: str
    amount: Money
    start: date

    def __post_init__(self):
        _check_pattern(self.pattern)
        if not isinstance(self.period_kind, str) or self.period_kind not in _KINDS:
            raise BudgetError("invalid period kind %r: use month, quarter or year" % (self.period_kind,))
        if not isinstance(self.amount, Money):
            raise BudgetError("budget amount must be money, not %r" % (self.amount,))
        if self.amount.minor <= 0:
            raise BudgetError("budget amount must be greater than zero, not %s" % (self.amount,))
        if not is_date(self.start):
            raise BudgetError("budget start must be a date, not %r" % (self.start,))

    def matches(self, account):
        """True when the account is an expense account named by the pattern or below it."""
        segs = account.split(":")
        if segs[0] != "Expenses":
            return False
        pat = self.pattern.split(":")
        if len(segs) < len(pat):
            return False
        return all(p == "*" or p == s for p, s in zip(pat, segs))


@dataclass(frozen=True)
class BudgetLine:
    pattern: str
    period_kind: str
    budget: Money
    actual: Money
    remaining: Money
    percent: Decimal
    over: bool
    accounts: Tuple[Tuple[str, Money], ...]

    def to_dict(self):
        return {
            "pattern": self.pattern,
            "period_kind": self.period_kind,
            "budget": money_to_dict(self.budget),
            "actual": money_to_dict(self.actual),
            "remaining": money_to_dict(self.remaining),
            "percent": str(self.percent),
            "over": self.over,
            "accounts": [{"account": a, "amount": money_to_dict(m)} for a, m in self.accounts],
        }


# -- calendar arithmetic on month indexes ------------------------------------

def _first_ordinal(month_index):
    year, month = divmod(month_index, 12)
    if year > 9999:
        return date.max.toordinal() + 1
    return date(year, month + 1, 1).toordinal()


def _allowance(budget, period):
    """The allowance in the asked period, or None when the budget is not in force."""
    step = _STEP[budget.period_kind]
    first = budget.start.year * 12 + budget.start.month - 1
    first -= first % step
    first_ord = _first_ordinal(first)
    p_start, p_end = period.start.toordinal(), period.end.toordinal()
    if p_end < first_ord:
        return None
    lo = max(p_start, first_ord)
    date_lo = date.fromordinal(lo)
    idx = date_lo.year * 12 + date_lo.month - 1
    idx -= idx % step
    total = Fraction(0)
    begin = _first_ordinal(idx)
    while begin <= p_end:
        nxt = _first_ordinal(idx + step)
        overlap = min(p_end, nxt - 1) - max(p_start, begin) + 1
        if overlap > 0:
            total += Fraction(overlap, nxt - begin)
        idx += step
        begin = nxt
    scaled = total * budget.amount.minor
    return Money(round_div(scaled.numerator, scaled.denominator), budget.amount.currency)


def _percent(actual, allowance):
    if allowance == 0:
        return Decimal("0.0") if actual == 0 else Decimal("100.0")
    tenths = round_div(actual * 1000, allowance)
    sign = "-" if tenths < 0 else ""
    whole, frac = divmod(abs(tenths), 10)
    return Decimal("%s%d.%d" % (sign, whole, frac))


def budget_status(budgets, ledger, period):
    if not isinstance(period, Period):
        raise BudgetError("period must be a Period, not %r" % (period,))
    budgets = list(budgets)
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("not a budget: %r" % (b,))
    spent = {}
    for tx, posting in ledger.postings():
        if posting.amount is None or not period.contains(tx.date):
            continue
        key = (posting.account, posting.amount.currency)
        spent[key] = spent.get(key, 0) + posting.amount.minor
    ordered = sorted(budgets, key=lambda b: (b.pattern, _KINDS.index(b.period_kind), b.start))
    lines = []
    for b in ordered:
        allowance = _allowance(b, period)
        if allowance is None:
            continue
        cur = b.amount.currency
        per_account = sorted(
            (acct, minor) for (acct, c), minor in spent.items()
            if c == cur and minor != 0 and b.matches(acct)
        )
        total = 0
        for acct, minor in per_account:
            total += minor
        actual = Money(total, cur)
        # the total counts zero-sum accounts too, which add nothing
        lines.append(BudgetLine(
            b.pattern, b.period_kind, allowance, actual, allowance - actual,
            _percent(actual.minor, allowance.minor), actual.minor > allowance.minor,
            tuple((acct, Money(minor, cur)) for acct, minor in per_account),
        ))
    return lines

