"""Reports: trial balance, balance sheet, income statement, cash flow, register, net worth."""
from tallybook.currency import currency as _known_currency
from tallybook.currency import is_date
from tallybook.dates import Period, format_date, periods
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, render_table, to_csv
from tallybook.money import Money, format_minor, round_div

_TYPES = {"Assets": "asset", "Liabilities": "liability", "Equity": "equity",
          "Income": "income", "Expenses": "expense"}
_STEPS = ("week", "month", "quarter", "year")


class ReportError(ValidationError):
    pass


# -- small helpers -------------------------------------------------------------

def _type(account):
    return _TYPES[account.split(":", 1)[0]]


def _money(minor, cur):
    return {"amount": format_minor(minor, cur), "currency": cur}


def _money_list(sums, only=None):
    """Money objects for a {currency: minor} dict, sorted by currency."""
    return [_money(sums[c], c) for c in sorted(sums)]


def _day(d):
    return None if d is None else format_date(d)


def _check_as_of(as_of):
    if as_of is not None and not is_date(as_of):
        raise ReportError("as_of must be a date or None, not %r" % (as_of,))


def _check_period(period):
    if not isinstance(period, Period):
        raise ReportError("period must be a Period, not %r" % (period,))


def _percent(num, den):
    """num / den * 100 as text with one decimal, halves away from zero."""
    if den == 0:
        return "0.0"
    if den < 0:
        num, den = -num, -den
    tenths = round_div(num * 1000, den)
    whole, frac = divmod(abs(tenths), 10)
    return "%s%d.%d" % ("-" if tenths < 0 else "", whole, frac)


def _add(sums, cur, minor):
    sums[cur] = sums.get(cur, 0) + minor


def _convert_target(ledger, convert_to):
    if convert_to is not None:
        _known_currency(convert_to)


def _convert(ledger, minor, cur, convert_to, on):
    """Minor units of the converted amount (a line already in convert_to is unchanged)."""
    return ledger.rates.convert(Money(minor, cur), convert_to, on).minor


# -- trial balance ---------------------------------------------------------------

def trial_balance(ledger, as_of):
    _check_as_of(as_of)
    bal = ledger.balances(as_of)
    accounts = []
    debits, credits = {}, {}
    for account in sorted(bal):
        for cur in sorted(bal[account]):
            minor = bal[account][cur]
            entry = {"account": account, "type": _type(account), "debit": None, "credit": None}
            if minor > 0:
                entry["debit"] = _money(minor, cur)
                _add(debits, cur, minor)
                credits.setdefault(cur, 0)
            else:
                entry["credit"] = _money(-minor, cur)
                _add(credits, cur, -minor)
                debits.setdefault(cur, 0)
            accounts.append(entry)
    totals = [{"currency": c, "debit": _money(debits[c], c), "credit": _money(credits[c], c),
               "balanced": debits[c] == credits[c]} for c in sorted(debits)]
    return {"report": "trial_balance", "as_of": _day(as_of), "accounts": accounts, "totals": totals}


# -- balance sheet -----------------------------------------------------------------

def _section_total(lines, extra=None):
    sums = {}
    for _, cur, minor in lines:
        _add(sums, cur, minor)
    for cur, minor in (extra or {}).items():
        _add(sums, cur, minor)
    return sums


def balance_sheet(ledger, as_of, convert_to=None, today=None):
    _check_as_of(as_of)
    if convert_to is not None:
        _convert_target(ledger, convert_to)
        if as_of is None:
            raise ReportError("converting needs a date: give as_of with convert_to")
    bal = ledger.balances(as_of)
    lines = {"asset": [], "liability": [], "equity": []}
    earned = {}
    for account in sorted(bal):
        kind = _type(account)
        for cur in sorted(bal[account]):
            minor = bal[account][cur]
            if kind == "asset":
                lines["asset"].append((account, cur, minor))
            elif kind in ("liability", "equity"):
                lines[kind].append((account, cur, -minor))
            else:
                _add(earned, cur, -minor)
    earned = {c: v for c, v in earned.items() if v != 0}

    def section(kind, with_retained):
        entries = []
        for account, cur, minor in lines[kind]:
            if convert_to is None:
                entries.append({"account": account, "balance": _money(minor, cur)})
            else:
                entries.append({"account": account,
                                "balance": _money(_convert(ledger, minor, cur, convert_to, as_of), convert_to),
                                "original": _money(minor, cur)})
        out = {"accounts": entries}
        if convert_to is None:
            if with_retained:
                out["retained_earnings"] = _money_list(earned)
            sums = _section_total(lines[kind], earned if with_retained else None)
            out["total"] = _money_list(sums)
            return out, sums
        total = sum(_convert(ledger, m, c, convert_to, as_of) for _, c, m in lines[kind])
        if with_retained:
            conv = [_convert(ledger, m, c, convert_to, as_of) for c, m in sorted(earned.items())]
            out["retained_earnings"] = [_money(sum(conv), convert_to)] if earned else []
            total += sum(conv)
        out["total"] = [_money(total, convert_to)]
        return out, {convert_to: total}

    assets, a_sums = section("asset", False)
    liabilities, l_sums = section("liability", False)
    equity, e_sums = section("equity", True)
    balanced = all(a_sums.get(c, 0) == l_sums.get(c, 0) + e_sums.get(c, 0)
                   for c in set(a_sums) | set(l_sums) | set(e_sums))
    return {"report": "balance_sheet", "as_of": _day(as_of), "currency": convert_to,
            "assets": assets, "liabilities": liabilities, "equity": equity, "balanced": balanced}


# -- income statement ------------------------------------------------------------------

def income_statement(ledger, period, convert_to=None):
    _check_period(period)
    _convert_target(ledger, convert_to)
    sums = {"income": {}, "expense": {}}
    for tx, p in ledger.postings():
        if p.amount is None or not period.contains(tx.date):
            continue
        kind = _type(p.account)
        if kind not in sums:
            continue
        key = (p.account, p.amount.currency)
        sums[kind][key] = sums[kind].get(key, 0) + (-p.amount.minor if kind == "income" else p.amount.minor)
    lines = {k: [(a, c, v) for (a, c), v in sorted(sums[k].items()) if v != 0] for k in sums}

    def section(kind):
        rows = lines[kind]
        if convert_to is None:
            totals = _section_total(rows)
            entries = [{"account": a, "amount": _money(v, c), "percent": _percent(v, totals[c])}
                       for a, c, v in rows]
            return {"accounts": entries, "total": _money_list(totals)}, totals
        conv = [(a, c, v, _convert(ledger, v, c, convert_to, period.end)) for a, c, v in rows]
        total = sum(x[3] for x in conv)
        entries = [{"account": a, "amount": _money(cv, convert_to), "percent": _percent(cv, total),
                    "original": _money(v, c)} for a, c, v, cv in conv]
        return {"accounts": entries, "total": [_money(total, convert_to)]}, {convert_to: total}

    income, i_sums = section("income")
    expenses, e_sums = section("expense")
    net = {c: i_sums.get(c, 0) - e_sums.get(c, 0) for c in set(i_sums) | set(e_sums)}
    if convert_to is not None:
        net = {convert_to: i_sums[convert_to] - e_sums[convert_to]}
    return {"report": "income_statement", "start": format_date(period.start), "end": format_date(period.end),
            "currency": convert_to, "income": income, "expenses": expenses, "net": _money_list(net)}


# -- cash flow -------------------------------------------------------------------------

def cashflow(ledger, period):
    _check_period(period)
    opening, closing, seen = {}, {}, set()
    moves = {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            break
        asset = {}
        for p in tx.postings:
            if p.amount is not None and _type(p.account) == "asset":
                cur = p.amount.currency
                seen.add(cur)
                _add(asset, cur, p.amount.minor)
                _add(closing, cur, p.amount.minor)
                if tx.date < period.start:
                    _add(opening, cur, p.amount.minor)
        if tx.date < period.start:
            continue
        for p in tx.postings:
            if p.amount is None or _type(p.account) == "asset":
                continue
            cur = p.amount.currency
            if asset.get(cur, 0) != 0:
                key = (p.account, cur)
                moves[key] = moves.get(key, 0) - p.amount.minor
    inflows, outflows = [], []
    total_in = {c: 0 for c in seen}
    total_out = {c: 0 for c in seen}
    for (account, cur), v in sorted(moves.items()):
        if v > 0:
            inflows.append({"account": account, "amount": _money(v, cur)})
            total_in[cur] += v
        elif v < 0:
            outflows.append({"account": account, "amount": _money(-v, cur)})
            total_out[cur] += -v
    net = {c: total_in[c] - total_out[c] for c in seen}
    zero = {c: 0 for c in seen}
    return {"report": "cashflow", "start": format_date(period.start), "end": format_date(period.end),
            "opening": _money_list({c: opening.get(c, 0) for c in zero}),
            "inflows": inflows, "outflows": outflows,
            "total_in": _money_list(total_in), "total_out": _money_list(total_out),
            "net": _money_list(net),
            "closing": _money_list({c: closing.get(c, 0) for c in zero})}


# -- register --------------------------------------------------------------------------

def register(ledger, account, period=None, rollup=False):
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account: %s" % (account,))
    if period is not None:
        _check_period(period)
    prefix = account + ":"
    opening, running, seen = {}, {}, set()
    rows = []
    for tx, p in ledger.postings():
        if p.amount is None:
            continue
        if not (p.account == account or (rollup and p.account.startswith(prefix))):
            continue
        if period is not None and tx.date > period.end:
            continue
        cur = p.amount.currency
        seen.add(cur)
        _add(running, cur, p.amount.minor)
        if period is not None and tx.date < period.start:
            _add(opening, cur, p.amount.minor)
            continue
        rows.append({"date": format_date(tx.date), "id": tx.id, "payee": tx.payee,
                     "narration": tx.narration, "account": p.account,
                     "amount": _money(p.amount.minor, cur),
                     "balance": _money(running[cur], cur)})
    return {"report": "register", "account": account, "rollup": bool(rollup),
            "start": None if period is None else format_date(period.start),
            "end": None if period is None else format_date(period.end),
            "opening": _money_list({c: opening.get(c, 0) for c in seen}),
            "rows": rows,
            "closing": _money_list({c: running.get(c, 0) for c in seen})}


# -- net worth -------------------------------------------------------------------------

def net_worth(ledger, period, step="month"):
    _check_period(period)
    if not isinstance(step, str) or step not in _STEPS:
        raise ReportError("unknown step %r: use week, month, quarter or year" % (step,))
    events = []
    for tx, p in ledger.postings():
        if p.amount is None:
            continue
        kind = _type(p.account)
        if kind in ("asset", "liability"):
            events.append((tx.date, kind, p.amount.currency, p.amount.minor))
    assets, liabilities, seen = {}, {}, set()
    i = 0
    points = []
    for step_period in periods(period.start, period.end, step):
        last = step_period.end
        while i < len(events) and events[i][0] <= last:
            _, kind, cur, minor = events[i]
            seen.add(cur)
            _add(assets if kind == "asset" else liabilities, cur, minor if kind == "asset" else -minor)
            i += 1
        points.append({
            "date": format_date(last),
            "assets": _money_list({c: assets.get(c, 0) for c in seen}),
            "liabilities": _money_list({c: liabilities.get(c, 0) for c in seen}),
            "net": _money_list({c: assets.get(c, 0) - liabilities.get(c, 0) for c in seen}),
        })
    return {"report": "net_worth", "start": format_date(period.start), "end": format_date(period.end),
            "step": step, "points": points}


# -- CSV -------------------------------------------------------------------------------

def _plain(m):
    return m["amount"]


def _csv_rows(report):
    kind = report["report"]
    if kind == "trial_balance":
        rows = []
        for e in report["accounts"]:
            side = e["debit"] if e["debit"] is not None else e["credit"]
            rows.append([e["account"], e["type"], side["currency"],
                         _plain(e["debit"]) if e["debit"] is not None else "",
                         _plain(e["credit"]) if e["credit"] is not None else ""])
        return ["account", "type", "currency", "debit", "credit"], rows
    if kind == "balance_sheet":
        rows = []
        for name in ("assets", "liabilities", "equity"):
            for e in report[name]["accounts"]:
                rows.append([name, e["account"], e["balance"]["currency"], _plain(e["balance"])])
        for m in report["equity"]["retained_earnings"]:
            rows.append(["equity", "Retained earnings", m["currency"], _plain(m)])
        return ["section", "account", "currency", "balance"], rows
    if kind == "income_statement":
        rows = []
        for name in ("income", "expenses"):
            for e in report[name]["accounts"]:
                rows.append([name, e["account"], e["amount"]["currency"], _plain(e["amount"]), e["percent"]])
        return ["section", "account", "currency", "amount", "percent"], rows
    if kind == "cashflow":
        rows = [["opening", "", m["currency"], _plain(m)] for m in report["opening"]]
        rows += [["in", e["account"], e["amount"]["currency"], _plain(e["amount"])] for e in report["inflows"]]
        rows += [["out", e["account"], e["amount"]["currency"], _plain(e["amount"])] for e in report["outflows"]]
        rows += [["closing", "", m["currency"], _plain(m)] for m in report["closing"]]
        return ["section", "account", "currency", "amount"], rows
    if kind == "register":
        rows = [[r["date"], "" if r["id"] is None else r["id"], r["payee"], r["narration"], r["account"],
                 r["amount"]["currency"], _plain(r["amount"]), _plain(r["balance"])] for r in report["rows"]]
        return ["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows
    if kind == "net_worth":
        rows = []
        for pt in report["points"]:
            for a, l, n in zip(pt["assets"], pt["liabilities"], pt["net"]):
                rows.append([pt["date"], a["currency"], _plain(a), _plain(l), _plain(n)])
        return ["date", "currency", "assets", "liabilities", "net"], rows
    raise ReportError("unknown report %r" % (kind,))


def report_to_csv(report):
    if not isinstance(report, dict) or "report" not in report:
        raise ReportError("not a report: %r" % (report,))
    try:
        headers, rows = _csv_rows(report)
    except (KeyError, TypeError, IndexError, AttributeError) as err:
        raise ReportError("malformed report: %r" % (err,))
    return to_csv(headers, rows)


# -- text --------------------------------------------------------------------------------

def _mt(m):
    return "%s %s" % (m["amount"], m["currency"])


def _blocks(blocks, width):
    """Join blocks that have rows with one row of empty cells between them."""
    rows = []
    for block in blocks:
        if not block:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(block)
    return rows


def _text_trial_balance(r):
    title = "Trial balance" if r["as_of"] is None else "Trial balance as of %s" % r["as_of"]
    rows = [[e["account"], e["type"], _mt(e["debit"]) if e["debit"] else "",
             _mt(e["credit"]) if e["credit"] else ""] for e in r["accounts"]]
    for t in r["totals"]:
        rows.append(["Total", "", _mt(t["debit"]), _mt(t["credit"])])
    return title, render_table(["Account", "Type", "Debit", "Credit"], rows, "llrr")


def _text_balance_sheet(r):
    title = "Balance sheet" if r["as_of"] is None else "Balance sheet as of %s" % r["as_of"]
    if r["currency"] is not None:
        title += " (in %s)" % r["currency"]
    blocks = []
    for heading, key, total_label in (("Assets", "assets", "Total assets"),
                                      ("Liabilities", "liabilities", "Total liabilities"),
                                      ("Equity", "equity", "Total equity")):
        sec = r[key]
        block = [[heading, ""]]
        block += [["  " + e["account"], _mt(e["balance"])] for e in sec["accounts"]]
        if key == "equity":
            block += [["  Retained earnings", _mt(m)] for m in sec["retained_earnings"]]
        block += [[total_label, _mt(m)] for m in sec["total"]]
        blocks.append(block)
    return title, render_table(["Account", "Balance"], _blocks(blocks, 2), "lr")


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r["currency"] is not None:
        title += " (in %s)" % r["currency"]
    blocks = []
    for heading, key, total_label in (("Income", "income", "Total income"),
                                      ("Expenses", "expenses", "Total expenses")):
        sec = r[key]
        block = [[heading, "", ""]]
        block += [["  " + e["account"], _mt(e["amount"]), e["percent"] + "%"] for e in sec["accounts"]]
        block += [[total_label, _mt(m), ""] for m in sec["total"]]
        blocks.append(block)
    blocks.append([["Net income", _mt(m), ""] for m in r["net"]])
    return title, render_table(["Account", "Amount", "Percent"], _blocks(blocks, 3), "lrr")


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])
    blocks = [[["Opening balance", _mt(m)] for m in r["opening"]]]
    for heading, items, total_label, totals in (("Money in", r["inflows"], "Total money in", r["total_in"]),
                                                ("Money out", r["outflows"], "Total money out", r["total_out"])):
        block = [[heading, ""]]
        block += [["  " + e["account"], _mt(e["amount"])] for e in items]
        block += [[total_label, _mt(m)] for m in totals]
        blocks.append(block)
    blocks.append([["Net change", _mt(m)] for m in r["net"]] + [["Closing balance", _mt(m)] for m in r["closing"]])
    return title, render_table(["Account", "Amount"], _blocks(blocks, 2), "lr")


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for pt in r["points"]:
        if not pt["assets"]:
            rows.append([pt["date"], "", "", ""])
        for a, l, n in zip(pt["assets"], pt["liabilities"], pt["net"]):
            rows.append([pt["date"], _mt(a), _mt(l), _mt(n)])
    return title, render_table(["Date", "Assets", "Liabilities", "Net"], rows, "lrrr")


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _mt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else row["id"], row["payee"], row["account"],
                     _mt(row["amount"]), _mt(row["balance"])])
    rows += [["", "", "Closing balance", "", "", _mt(m)] for m in r["closing"]]
    return title, render_table(["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr")


_TEXT = {"trial_balance": _text_trial_balance, "balance_sheet": _text_balance_sheet,
         "income_statement": _text_income_statement, "cashflow": _text_cashflow,
         "net_worth": _text_net_worth, "register": _text_register}


def render_text(report):
    if not isinstance(report, dict) or not isinstance(report.get("report"), str) or report["report"] not in _TEXT:
        raise ReportError("not a report: %r" % (report,))
    try:
        title, table = _TEXT[report["report"]](report)
    except (KeyError, TypeError, IndexError, AttributeError) as err:
        raise ReportError("malformed report: %r" % (err,))
    return title + "\n\n" + table

